1	//! Tests for enchantments, auras, and continuous effects.
2	
3	mod common;
4	
5	use common::*;
6	use mtg_engine::actions::{Action, Target};
7	use mtg_engine::cards::CardRegistry;
8	use mtg_engine::engine;
9	use mtg_engine::sba::check_state_based_actions_with_registry;
10	use mtg_engine::types::*;
11	use mtg_engine::view::GameView;
12	
13	/// Holy Strength attaches to a creature and gives +1/+2.
14	#[test]
15	fn holy_strength_buffs_creature() {
16	    let registry = CardRegistry::with_all_cards();
17	    let mut state = game_at_step(Step::PrecombatMain, P0);
18	
19	    let creature = ready_creature(&mut state, P0, 2, 2);
20	    let hs = castable_spell(&mut state, &registry, "Holy Strength", P0);
21	
22	    // Cast Holy Strength targeting creature.
23	    state = cast_and_resolve(&state, &registry, hs, vec![Target::Object(creature)]);
24	
25	    // Aura should be on battlefield, attached to creature.
26	    assert_eq!(state.get_object(hs).unwrap().zone, Zone::Battlefield);
27	    assert_eq!(state.get_object(hs).unwrap().attached_to, Some(creature));
28	
29	    // Creature should have effective +1/+2.
30	    assert_eq!(state.effective_power(creature, &registry), Some(3));
31	    assert_eq!(state.effective_toughness(creature, &registry), Some(4));
32	}
33	
34	/// Aura falls off when enchanted creature dies.
35	#[test]
36	fn aura_falls_off_when_creature_dies() {
37	    let registry = CardRegistry::with_all_cards();
38	    let mut state = game_at_step(Step::PrecombatMain, P0);
39	
40	    let creature = ready_creature(&mut state, P0, 2, 2);
41	    let hs = castable_spell(&mut state, &registry, "Holy Strength", P0);
42	
43	    // Attach Holy Strength.
44	    state = cast_and_resolve(&state, &registry, hs, vec![Target::Object(creature)]);
45	
46	    // Kill the creature.
47	    state.move_object(creature, Zone::Graveyard);
48	
49	    // SBA should put the unattached aura in graveyard.
50	    check_state_based_actions_with_registry(&mut state, Some(&registry));
51	    assert_eq!(state.get_object(hs).unwrap().zone, Zone::Graveyard);
52	}
53	
54	/// Pacifism prevents a creature from attacking.
55	#[test]
